import itertools

class StablePriorityQueue:
    def __init__(self):
        self._heap = []
        self._sequence = itertools.count()

    def push(self, priority, item):
        heapq.heappush(self._heap, (priority, next(self._sequence), item))

    def pop(self):
        return heapq.heappop(self._heap)[2]

import re

def roman_value(text):
    if not text or re.fullmatch(r'M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})', text) is None:
        raise ValueError('invalid Roman numeral')
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i, symbol in enumerate(text):
        value = values[symbol]
        total += -value if i + 1 < len(text) and value < values[text[i + 1]] else value
    return total

import heapq

class RunningMedian:
    def __init__(self):
        self.low = []
        self.high = []

    def add(self, value):
        heapq.heappush(self.low, -value)
        heapq.heappush(self.high, -heapq.heappop(self.low))
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def value(self):
        if not self.low:
            raise ValueError('no observations')
        if len(self.low) == len(self.high):
            return (-self.low[0] + self.high[0]) / 2
        return -self.low[0]

def permission_text(mode):
    result = []
    for shift in (6, 3, 0):
        triple = (mode >> shift) & 7
        result.append('r' if triple & 4 else '-')
        result.append('w' if triple & 2 else '-')
        result.append('x' if triple & 1 else '-')
    return ''.join(result)

from collections import deque

def dependency_order(edges):
    nodes = set(edges)
    for neighbors in edges.values():
        nodes.update(neighbors)
    incoming = {node: 0 for node in nodes}
    for neighbors in edges.values():
        for node in set(neighbors):
            incoming[node] += 1
    ready = deque(node for node in nodes if incoming[node] == 0)
    result = []
    while ready:
        node = ready.popleft()
        result.append(node)
        for child in set(edges.get(node, [])):
            incoming[child] -= 1
            if incoming[child] == 0:
                ready.append(child)
    if len(result) != len(nodes):
        raise ValueError('cyclic dependencies')
    return result
